// minCut brute-forces the minimum s-t cut by trying every vertex subset, which
// max-flow must equal. Only usable for very small n.
func minCut(n int, edges [][]int, s, t int) int {
	best := -1
	for mask := 0; mask < 1<<n; mask++ {
		if mask&(1<<s) == 0 || mask&(1<<t) != 0 {
			continue
		}
		sum := 0
		for _, e := range edges {
